# Adaptive Rejection Sampling (ARS) as described in Gilks et al. (1992)

# Helper function: Check input validity
validate_inputs <- function(density_function, domain, n) {
  if (!is.function(density_function)) {
    stop("density_function must be a function.")
  }
  if (!is.numeric(domain) || length(domain) != 2 || domain[1] >= domain[2]) {
    stop("domain must be a numeric vector of length 2 representing c(lower, upper).")
  }
  if (!is.numeric(n) || length(n) != 1 || n <= 0 || n != round(n)) {
    stop("n must be a positive integer representing sample count.")
  }
}

# Helper function: Check log-concavity (second derivative of log-density <= 0)
# We check this numerically at evaluation points using finite differences.
check_log_concavity <- function(log_density_fn, x) {
  h <- 1e-4
  val_mid <- log_density_fn(x)
  val_plus <- log_density_fn(x + h)
  val_minus <- log_density_fn(x - h)

  # Second derivative approximation: f''(x) = (f(x+h) - 2f(x) + f(x-h)) / h^2
  d2 <- (val_plus - 2 * val_mid + val_minus) / (h^2)

  # If second derivative is significantly positive, log-density is convex (not concave)
  if (d2 > 1e-2) {
    stop(paste0("Density function is not log-concave at x = ", x, ", second derivative of log-density is ", d2))
  }
}

# Adaptive Rejection Sampler main implementation
ars <- function(density_function, domain, n) {
  validate_inputs(density_function, domain, n)

  log_density <- function(x) {
    # vectorized or scalar
    res <- log(pmax(density_function(x), 1e-300))
    return(res)
  }

  # Initialize starting points (e.g., 3 points in the domain)
  # If domain has infinite bounds, bound them for initial points
  lower <- if (is.infinite(domain[1])) -3 else domain[1]
  upper <- if (is.infinite(domain[2])) 3 else domain[2]

  # Ensure initial points are well spaced
  x_pts <- sort(unique(c(lower, (lower + upper) / 2, upper)))
  if (length(x_pts) < 3) {
    x_pts <- seq(lower, upper, length.out = 3)
  }

  # Evaluate log density and derivative at initial points
  h <- 1e-4
  y_pts <- log_density(x_pts)

  # Check initial log-concavity
  for (xp in x_pts) {
    check_log_concavity(log_density, xp)
  }

  # Numerical derivative (slope) at initial points
  d_pts <- (log_density(x_pts + h) - log_density(x_pts - h)) / (2 * h)

  samples <- numeric(n)
  accepted <- 0

  while (accepted < n) {
    # Construct hulls (lower hull l(x) and upper hull u(x))
    # For each interval between x_pts, upper hull is linear tangent lines intersection
    k <- length(x_pts)

    # Calculate upper hull tangents
    # u_j(x) = y_j + d_j * (x - x_j)
    # Intersection of tangent at j and j+1:
    # z_j = (y_{j+1} - y_j - d_{j+1}*x_{j+1} + d_j*x_j) / (d_j - d_{j+1})
    z <- numeric(k - 1)
    for (j in 1:(k - 1)) {
      denom <- d_pts[j] - d_pts[j+1]
      if (abs(denom) < 1e-12) {
        z[j] <- (x_pts[j] + x_pts[j+1]) / 2
      } else {
        z[j] <- (y_pts[j+1] - y_pts[j] - d_pts[j+1] * x_pts[j+1] + d_pts[j] * x_pts[j]) / denom
      }
    }

    # Add outer bounds
    z_all <- c(domain[1], z, domain[2])

    # Calculate integrals of exp(u(x)) over each interval to sample from upper hull envelope
    # Intervals are [z_all[j], z_all[j+1]] for j = 1 to k
    interval_integrals <- numeric(k)
    for (j in 1:k) {
      z_l <- z_all[j]
      z_u <- z_all[j+1]
      yj <- y_pts[j]
      dj <- d_pts[j]

      if (is.infinite(z_l) || is.infinite(z_u)) {
        # Handle infinite bounds conservatively or approximate
        # For standard domains, z_l and z_u are finite due to initial bounds/extrapolation
        # But if infinite, use exponential approximation
        if (dj > 0) {
          interval_integrals[j] <- exp(yj + dj * (z_u - x_pts[j])) / dj
        } else if (dj < 0) {
          interval_integrals[j] <- -exp(yj + dj * (z_l - x_pts[j])) / dj
        } else {
          interval_integrals[j] <- exp(yj) * (z_u - z_l)
        }
      } else {
        if (abs(dj) < 1e-12) {
          interval_integrals[j] <- exp(yj) * (z_u - z_l)
        } else {
          interval_integrals[j] <- (exp(yj + dj * (z_u - x_pts[j])) - exp(yj + dj * (z_l - x_pts[j]))) / dj
        }
      }
    }

    # Normalize to get probabilities
    total_integral <- sum(interval_integrals)
    if (total_integral <= 0 || is.na(total_integral)) {
      # Fallback sampling if numerical issues occur
      total_integral <- 1
      probs <- rep(1 / k, k)
    } else {
      probs <- interval_integrals / total_integral
    }

    # Sample an interval index
    j_sampled <- sample.int(k, size = 1, prob = probs)

    # Sample x from upper hull in interval j_sampled using inverse CDF method for truncated exponential
    z_l <- z_all[j_sampled]
    z_u <- z_all[j_sampled + 1]
    yj <- y_pts[j_sampled]
    dj <- d_pts[j_sampled]
    xj <- x_pts[j_sampled]

    # Generate uniform for inverse CDF
    u_rand <- runif(1)

    if (is.infinite(z_l) || is.infinite(z_u)) {
      # Fallback uniform on bounded approximation
      x_cand <- runif(1, if(is.infinite(z_l)) -10 else z_l, if(is.infinite(z_u)) 10 else z_u)
    } else {
      if (abs(dj) < 1e-12) {
        x_cand <- z_l + u_rand * (z_u - z_l)
      } else {
        # CDF of exp(yj + dj*(x - xj)) from z_l to x_cand
        # Integral proportion = (exp(dj*(x_cand - xj)) - exp(dj*(z_l - xj))) / (exp(dj*(z_u - xj)) - exp(dj*(z_l - xj)))
        term1 <- exp(dj * (z_l - xj))
        term2 <- exp(dj * (z_u - xj))
        val <- term1 + u_rand * (term2 - term1)
        x_cand <- xj + log(pmax(val, 1e-300)) / dj
      }
    }

    # Ensure x_cand is within domain and z bounds
    x_cand <- max(domain[1], min(domain[2], x_cand))

    # Evaluate log density at candidate
    log_f_cand <- log_density(x_cand)

    # Check log concavity dynamically
    check_log_concavity(log_density, x_cand)

    # Calculate lower hull l(x_cand) at x_cand
    # Find which interval x_cand falls into
    # Lower hull is linear interpolation between adjacent x_pts
    l_val <- -Inf
    for (i in 1:(k - 1)) {
      if (x_cand >= x_pts[i] && x_cand <= x_pts[i+1]) {
        # Linear interpolation between (x_pts[i], y_pts[i]) and (x_pts[i+1], y_pts[i+1])
        slope <- (y_pts[i+1] - y_pts[i]) / (x_pts[i+1] - x_pts[i])
        l_val <- y_pts[i] + slope * (x_cand - x_pts[i])
        break
      }
    }

    # Upper hull value at x_cand
    u_val <- yj + dj * (x_cand - xj)

    # Squeeze test / rejection test
    w <- runif(1)

    # Lower hull test (squeeze)
    if (log(w) <= l_val - u_val) {
      accepted <- accepted + 1
      samples[accepted] <- x_cand
    } else {
      # Exact rejection test
      if (log(w) <= log_f_cand - u_val) {
        accepted <- accepted + 1
        samples[accepted] <- x_cand
      }

      # Update hull with new point x_cand
      x_pts <- sort(c(x_pts, x_cand))
      # Re-evaluate y_pts, d_pts
      y_pts <- log_density(x_pts)
      for (xp in x_pts) {
        check_log_concavity(log_density, xp)
      }
      d_pts <- (log_density(x_pts + h) - log_density(x_pts - h)) / (2 * h)
    }
  }

  return(samples)
}

# Formal testing function
test <- function() {
  cat("Running Adaptive Rejection Sampling (ARS) tests...\n\n")
  passed_tests <- 0
  total_tests <- 0

  # Test 1: Normal Distribution
  total_tests <- total_tests + 1
  test_name <- "TEST_NORMAL_DISTRIBUTION"
  tryCatch({
    set.seed(42)
    dnorm_fn <- function(x) dnorm(x, mean = 0, sd = 1)
    samples <- ars(dnorm_fn, domain = c(-5, 5), n = 1000)

    mu <- mean(samples)
    sigma <- sd(samples)

    # Save samples to file as requested
    writeLines(as.character(samples), "/app/normal_samples.txt")

    # Check if mean is close to 0 and sd close to 1
    if (abs(mu - 0) < 0.2 && abs(sigma - 1) < 0.2) {
      cat(paste0(test_name, ": PASS (Mean: ", round(mu, 4), ", SD: ", round(sigma, 4), ")\n"))
      passed_tests <- passed_tests + 1
    } else {
      cat(paste0(test_name, ": FAIL (Mean: ", round(mu, 4), ", SD: ", round(sigma, 4), ")\n"))
    }
  }, error = function(e) {
    cat(paste0(test_name, ": FAIL (Error: ", e$message, ")\n"))
  })

  # Test 2: Exponential Distribution
  total_tests <- total_tests + 1
  test_name <- "TEST_EXPONENTIAL_DISTRIBUTION"
  tryCatch({
    set.seed(42)
    dexp_fn <- function(x) dexp(x, rate = 1)
    samples <- ars(dexp_fn, domain = c(0.01, 10), n = 1000)

    mu <- mean(samples)
    sigma <- sd(samples)

    # Save samples to file
    writeLines(as.character(samples), "/app/exponential_samples.txt")

    # For Exp(1), mean = 1, sd = 1
    if (abs(mu - 1) < 0.2 && abs(sigma - 1) < 0.2) {
      cat(paste0(test_name, ": PASS (Mean: ", round(mu, 4), ", SD: ", round(sigma, 4), ")\n"))
      passed_tests <- passed_tests + 1
    } else {
      cat(paste0(test_name, ": FAIL (Mean: ", round(mu, 4), ", SD: ", round(sigma, 4), ")\n"))
    }
  }, error = function(e) {
    cat(paste0(test_name, ": FAIL (Error: ", e$message, ")\n"))
  })

  # Test 3: Input Validation (Negative sample count)
  total_tests <- total_tests + 1
  test_name <- "TEST_INPUT_VALIDATION_NEGATIVE_N"
  tryCatch({
    ars(function(x) dnorm(x), domain = c(-3, 3), n = -10)
    cat(paste0(test_name, ": FAIL (Should have rejected negative n)\n"))
  }, error = function(e) {
    cat(paste0(test_name, ": PASS (Correctly caught invalid input: ", e$message, ")\n"))
    passed_tests <- passed_tests + 1
  })

  # Test 4: Non-log-concave density check (e.g., Student's t or mixture of normals which is non-log-concave)
  total_tests <- total_tests + 1
  test_name <- "TEST_NON_LOG_CONCAVE_DETECTION"
  tryCatch({
    # Mixture of two normals: not log-concave
    non_log_concave_fn <- function(x) dnorm(x, mean = -2, sd = 0.5) + dnorm(x, mean = 2, sd = 0.5)
    ars(non_log_concave_fn, domain = c(-5, 5), n = 100)
    cat(paste0(test_name, ": FAIL (Should have detected non-log-concavity)\n"))
  }, error = function(e) {
    cat(paste0(test_name, ": PASS (Correctly detected non-log-concave density: ", e$message, ")\n"))
    passed_tests <- passed_tests + 1
  })

  cat(sprintf("\nTest Summary: %d / %d tests passed.\n", passed_tests, total_tests))
}
